insert into videos (id, user_id, title, language, speaker, voiced, captions, status, progress, error, seconds, steps, characters, is_public, script, outline, views, created_at, finished_at, published_at, subject) VALUES ('f9683b795bb7', '52061686-0664-40b2-8dd3-99457b33ce76', 'Binary search, step by step', 'te', NULL, false, true, 'done', 'finished', NULL, 31.680767, 7, 0, true, '{"title": "Binary search, step by step", "canvas": {"fps": 30, "theme": "dark", "width": 960, "height": 540}, "scenes": [{"id": "setup", "steps": [{"do": [{"action": "write", "target": "heading"}, {"delay": 0.2, "action": "show", "target": "arr"}], "say": {"en": "We are looking for 23 in this sorted array.", "hi": "इस sorted array में हम 23 को search कर रहे हैं।", "te": "ఈ sorted array లో మనం 23 ను search చేస్తున్నాం."}}, {"do": [{"action": "show", "target": "lo"}, {"delay": 0.3, "action": "show", "target": "hi"}], "say": {"en": "Two pointers, lo and hi, mark the part we still have to search.", "hi": "lo और hi, ये two pointers उस part को mark करते हैं जहाँ हमें अभी search करना है।", "te": "lo, hi అనే two pointers, మనం ఇంకా search చేయాల్సిన part ను mark చేస్తాయి."}}]}, {"id": "first-check", "steps": [{"do": [{"action": "show", "target": "mid"}, {"action": "highlight", "target": "arr[3]"}], "say": {"en": "Look at the middle element, which is 12.", "hi": "Middle element को देखिए, वह 12 है।", "te": "Middle element ను చూడండి, అది 12."}}, {"do": [{"action": "dim", "target": "arr[0..=3]"}, {"to": "arr[4]", "delay": 0.5, "action": "point", "target": "lo"}], "say": {"en": "12 is smaller than 23, so the left half cannot hold the answer.", "hi": "12, 23 से smaller है, इसलिए answer left half में नहीं हो सकता।", "te": "12 అనేది 23 కంటే smaller, కాబట్టి answer left half లో ఉండదు."}}]}, {"id": "second-check", "steps": [{"do": [{"to": "arr[5]", "action": "point", "target": "mid"}, {"delay": 0.5, "action": "highlight", "target": "arr[5]"}], "say": {"en": "The new middle sits at index 5.", "hi": "New middle अब index 5 पर है।", "te": "New middle ఇప్పుడు index 5 దగ్గర ఉంది."}}, {"do": [{"action": "show", "target": "note"}], "say": {"en": "That is 23, the value we wanted, found in only two checks.", "hi": "वह 23 है, वही value जो हमें चाहिए थी। Only two checks में found हो गई।", "te": "అది 23, మనకు కావాల్సిన value. Only two checks లోనే found అయ్యింది."}}, {"do": [{"text": "About log n checks", "action": "replace", "target": "note"}], "say": {"en": "Each check halves what is left, so binary search needs about log n steps.", "hi": "हर check में remaining part half हो जाता है, इसलिए binary search को about log n steps ही लगते हैं।", "te": "ప్రతి check తో remaining part half అవుతుంది, కాబట్టి binary search కు about log n steps చాలు."}}]}], "objects": [{"id": "heading", "text": "Binary search", "type": "text", "region": "title"}, {"id": "arr", "type": "array", "region": "center", "values": [2, 5, 8, 12, 16, 23, 38]}, {"id": "lo", "type": "pointer", "label": "lo", "target": "arr[0]"}, {"id": "hi", "type": "pointer", "label": "hi", "target": "arr[6]"}, {"id": "mid", "type": "pointer", "label": "mid", "target": "arr[3]"}, {"id": "note", "text": "Found 23 at index 5", "type": "text", "region": "bottom"}], "version": 1}', '[{"scene": "setup", "steps": 2, "seconds": 8, "opens_with": "ఈ sorted array లో మనం 23 ను search చేస్తున్నాం."}, {"scene": "first-check", "steps": 2, "seconds": 7, "opens_with": "Middle element ను చూడండి, అది 12."}, {"scene": "second-check", "steps": 3, "seconds": 13, "opens_with": "New middle ఇప్పుడు index 5 దగ్గర ఉంది."}]', 0, '2026-10-04 03:49:31.757288+00', '2026-10-04 03:49:40.41006+00', '2026-10-04 03:49:56.991603+00', 'dsa') on conflict (id) do nothing;
insert into videos (id, user_id, title, language, speaker, voiced, captions, status, progress, error, seconds, steps, characters, is_public, script, outline, views, created_at, finished_at, published_at, subject) VALUES ('1d104c19d006', '52061686-0664-40b2-8dd3-99457b33ce76', 'PCA by hand: every step explained', 'te', NULL, false, true, 'done', 'finished', NULL, 503.37698, 58, 0, true, '{"title": "PCA by hand: every step explained", "canvas": {"width": 960, "height": 540}, "scenes": [{"id": "overview", "steps": [{"do": [{"action": "write", "target": "heading"}], "say": {"en": "Principal component analysis, or PCA, replaces several related features with fewer new ones, while keeping as much of the information as it can.", "hi": "Principal component analysis, यानी PCA, कई related features को कुछ new features से replace करता है, लेकिन maximum information retain करता है।", "te": "Principal component analysis, అంటే PCA, చాలా related features ను కొన్ని new features తో replace చేస్తుంది, కానీ maximum information ను retain చేస్తుంది."}}, {"do": [{"action": "show", "target": "roadmap"}], "say": {"en": "Every PCA question in an exam is solved with the same six steps.", "hi": "Exam में हर PCA question इन्हीं six steps से solve होता है।", "te": "Exam లో ప్రతి PCA question ను ఇవే six steps తో solve చేస్తాం."}}, {"do": [{"action": "highlight", "target": "roadmap[0]"}], "say": {"en": "We will work through each one by hand on four points, saying where every number comes from and why the step is needed.", "hi": "हम four points लेकर हर step by hand solve करेंगे, और explain करते चलेंगे कि हर number कहाँ से आया और वह step क्यों needed है।", "te": "Four points తీసుకుని ప్రతి step ను by hand solve చేద్దాం. ప్రతి number ఎక్కడి నుంచి వచ్చిందో, ఆ step ఎందుకు need అవుతుందో explain చేస్తూ వెళ్దాం."}}]}, {"id": "centre", "steps": [{"do": [{"text": "Step 1 of 6: centre the data", "action": "replace", "target": "heading"}, {"action": "hide", "target": "roadmap"}, {"action": "show", "target": "data"}, {"delay": 0.3, "action": "show", "target": "cloud"}], "say": {"en": "Here is the data: four points, A to D, each with two features called x and y.", "hi": "यह है हमारा data: A से D तक four points। हर point के two features हैं, x और y।", "te": "ఇది మన data: A నుంచి D వరకు four points. ప్రతి point కు x, y అనే two features ఉన్నాయి."}}, {"do": [{"action": "show", "target": "formula"}], "say": {"en": "PCA measures how the data spreads around its centre, so the first thing we need is that centre: the mean of each feature.", "hi": "PCA यह measure करता है कि data अपने centre के around कितना spread है। इसलिए first हमें वह centre चाहिए, यानी हर feature का mean।", "te": "Data తన centre చుట్టూ ఎంత spread అయ్యిందో PCA measure చేస్తుంది. కాబట్టి first మనకు ఆ centre కావాలి, అంటే ప్రతి feature యొక్క mean."}}, {"do": [{"action": "highlight", "target": "formula[0]"}], "say": {"en": "In this formula, x bar is the mean of x, n is the number of points, and the sigma sign means add up every x value.", "hi": "इस formula में x bar, x का mean है, n number of points है, और sigma symbol का मतलब है सारी x values add करो।", "te": "ఈ formula లో x bar అంటే x యొక్క mean, n అంటే number of points, sigma symbol అంటే అన్ని x values ను add చేయడం."}}, {"do": [{"action": "reset", "target": "formula"}, {"action": "mark", "target": "data.x"}, {"delay": 0.2, "value": "overline(x) = (2 + 4 + 5 + 5) / 4 = 16 / 4 = 4", "action": "set", "target": "formula[0]"}], "say": {"en": "For x we add two, four, five and five to get sixteen, and divide by n, which is four. The mean of x is four.", "hi": "x के लिए 2, 4, 5 और 5 add करने पर 16 आता है। उसे n से, यानी 4 से divide करने पर x का mean 4 है।", "te": "x కోసం 2, 4, 5, 5 add చేస్తే 16 వస్తుంది. దాన్ని n తో, అంటే 4 తో divide చేస్తే, x యొక్క mean 4."}}, {"do": [{"action": "reset", "target": "data"}, {"action": "mark", "target": "data.y"}, {"delay": 0.2, "value": "overline(x) = 4 quad quad overline(y) = (2 + 3 + 2 + 5) / 4 = 12 / 4 = 3", "action": "set", "target": "formula[0]"}], "say": {"en": "For y we add two, three, two and five to get twelve, and twelve divided by four is three.", "hi": "y के लिए 2, 3, 2 और 5 add करने पर 12 आता है। 12 divided by 4 यानी 3।", "te": "y కోసం 2, 3, 2, 5 add చేస్తే 12 వస్తుంది. 12 divided by 4 అంటే 3."}}, {"do": [{"action": "reset", "target": "data"}, {"at": [4, 3], "id": "m", "label": "mean", "action": "add_point", "target": "cloud"}], "say": {"en": "So the centre of the data is the point four, three.", "hi": "तो data का centre, 4, 3 वाला point है।", "te": "కాబట్టి data యొక్క centre, 4, 3 అనే point."}}, {"do": [{"action": "highlight", "target": "data[0]"}, {"delay": 0.3, "value": -2, "action": "set", "target": "data[0][3]"}, {"delay": 0.5, "value": -1, "action": "set", "target": "data[0][4]"}, {"at": [-2, -1], "delay": 0.5, "action": "move_to", "target": "cloud.a"}], "say": {"en": "Now we subtract the mean from every point. For A, two minus four is minus two, and two minus three is minus one.", "hi": "अब हर point से mean subtract करते हैं। A के लिए, 2 minus 4 यानी minus 2, और 2 minus 3 यानी minus 1।", "te": "ఇప్పుడు ప్రతి point నుంచి mean ను subtract చేద్దాం. A కోసం, 2 minus 4 అంటే minus 2, 2 minus 3 అంటే minus 1."}}, {"do": [{"action": "highlight", "target": "data[1]"}, {"delay": 0.3, "value": 0, "action": "set", "target": "data[1][3]"}, {"delay": 0.5, "value": 0, "action": "set", "target": "data[1][4]"}, {"at": [0, 0], "delay": 0.5, "action": "move_to", "target": "cloud.b"}], "say": {"en": "For B, four minus four is zero and three minus three is zero, so B sits exactly at the centre.", "hi": "B के लिए, 4 minus 4 zero है और 3 minus 3 भी zero। यानी B exactly centre पर है।", "te": "B కోసం, 4 minus 4 zero, 3 minus 3 కూడా zero. అంటే B exactly centre దగ్గరే ఉంది."}}, {"do": [{"action": "highlight", "target": "data[2..4]"}, {"delay": 0.1, "value": 1, "action": "set", "target": "data[2][3]"}, {"delay": 0.2, "value": -1, "action": "set", "target": "data[2][4]"}, {"at": [1, -1], "delay": 0.2, "action": "move_to", "target": "cloud.c"}, {"delay": 0.5, "value": 1, "action": "set", "target": "data[3][3]"}, {"delay": 0.6, "value": 2, "action": "set", "target": "data[3][4]"}, {"at": [1, 2], "delay": 0.6, "action": "move_to", "target": "cloud.d"}], "say": {"en": "C becomes one, minus one. D becomes one, two.", "hi": "C बन जाता है 1, minus 1। D बन जाता है 1, 2।", "te": "C అనేది 1, minus 1 అవుతుంది. D అనేది 1, 2 అవుతుంది."}}, {"do": [{"action": "reset", "target": "data"}, {"action": "dim", "target": "data.x"}, {"action": "dim", "target": "data.y"}, {"action": "mark", "target": "data.c3"}, {"action": "mark", "target": "data.c4"}, {"at": [0, 0], "action": "move_to", "target": "cloud.m"}], "say": {"en": "The cloud keeps its shape, but its centre has moved to the origin. From now on we use only these centred values.", "hi": "Points की shape change नहीं हुई, लेकिन centre अब origin पर move हो गया है। आगे हम only यही centred values use करेंगे।", "te": "Points యొక్క shape change అవ్వలేదు, కానీ centre ఇప్పుడు origin కు move అయ్యింది. ఇకపై ఈ centred values మాత్రమే use చేస్తాం."}}, {"do": [{"action": "remove", "target": "cloud.m"}], "say": {"en": "We do this because without centring, the result would describe where the data is, instead of how it spreads.", "hi": "ऐसा इसलिए करते हैं क्योंकि centring के बिना result यह describe करेगा कि data कहाँ है, यह नहीं कि वह कैसे spread है।", "te": "ఇది ఎందుకు చేస్తామంటే, centring లేకపోతే result మనకు data ఎక్కడ ఉందో describe చేస్తుంది, అది ఎలా spread అయ్యిందో కాదు."}}]}, {"id": "covariance", "steps": [{"do": [{"text": "Step 2 of 6: covariance matrix", "action": "replace", "target": "heading"}, {"action": "hide", "target": "data"}, {"action": "show", "target": "work"}, {"value": "C = mat(\"var\"(x), \"cov\"(x, y); \"cov\"(x, y), \"var\"(y))", "action": "set", "target": "formula[0]"}], "say": {"en": "Step two. We need to know how much each feature spreads, and whether the two move together. The covariance matrix holds exactly that.", "hi": "Step 2. हमें जानना है कि हर feature कितना spread है, और दोनों together move करते हैं या नहीं। Covariance matrix में exactly यही होता है।", "te": "Step 2. ప్రతి feature ఎంత spread అయ్యిందో, రెండూ together move అవుతున్నాయో లేదో తెలియాలి. Covariance matrix లో exactly అదే ఉంటుంది."}}, {"do": [{"action": "highlight", "target": "formula[0]"}], "say": {"en": "The diagonal holds the variance of x and of y. The other two entries are the covariance between them, and they are always equal, so we need three numbers.", "hi": "Diagonal पर x का variance और y का variance होता है। Other two entries उनके बीच का covariance हैं। वे always equal होती हैं, इसलिए हमें three numbers चाहिए।", "te": "Diagonal లో x యొక్క variance, y యొక్క variance ఉంటాయి. Other two entries వాటి మధ్య covariance. అవి always equal, కాబట్టి మనకు three numbers చాలు."}}, {"do": [{"action": "reset", "target": "formula"}, {"action": "mark", "target": "work.c1"}, {"action": "mark", "target": "work.c2"}], "say": {"en": "In the table, x tilde and y tilde are the centred values we just found. The tilde simply means the mean has been subtracted.", "hi": "Table में x tilde और y tilde वही centred values हैं जो अभी find कीं। Tilde का मतलब बस यह है कि mean subtract हो चुका है।", "te": "Table లో x tilde, y tilde అంటే ఇప్పుడే find చేసిన centred values. Tilde అంటే mean ను subtract చేశామని meaning, అంతే."}}, {"do": [{"action": "reset", "target": "work"}, {"value": "\"var\"(x) = 1 / (n - 1) sum_(i=1)^n tilde(x)_i^2", "action": "set", "target": "formula[0]"}], "say": {"en": "Variance is the average squared distance from the mean. Since the data is centred, we square each x tilde, add them up, and divide by n minus one.", "hi": "Variance, mean से average squared distance है। Data centred है, इसलिए हर x tilde को square करते हैं, add करते हैं, और n minus 1 से divide करते हैं।", "te": "Variance అంటే mean నుంచి average squared distance. Data centred కాబట్టి, ప్రతి x tilde ను square చేసి, add చేసి, n minus 1 తో divide చేస్తాం."}}, {"do": [{"action": "highlight", "target": "formula[0]"}], "say": {"en": "We divide by n minus one, not n, because these points are a sample. Use n only if the question says the data is the whole population.", "hi": "हम n से नहीं, n minus 1 से divide करते हैं, क्योंकि ये points एक sample हैं। n तभी use करें जब question कहे कि data whole population है।", "te": "n తో కాకుండా n minus 1 తో divide చేస్తాం, ఎందుకంటే ఈ points ఒక sample. Data whole population అని question లో చెబితే మాత్రమే n use చేయాలి."}}, {"do": [{"action": "reset", "target": "formula"}, {"delay": 0.2, "value": 4, "action": "set", "target": "work[0][3]"}, {"delay": 0.5, "value": 0, "action": "set", "target": "work[1][3]"}, {"delay": 0.65, "value": 1, "action": "set", "target": "work[2][3]"}, {"delay": 0.8, "value": 1, "action": "set", "target": "work[3][3]"}], "say": {"en": "Square each x tilde: minus two squared is four, then zero, one and one.", "hi": "हर x tilde को square करें: minus 2 square यानी 4, फिर 0, 1 और 1।", "te": "ప్రతి x tilde ను square చేద్దాం: minus 2 square అంటే 4, తర్వాత 0, 1, 1."}}, {"do": [{"value": 6, "action": "set", "target": "work[4][3]"}, {"delay": 0.2, "action": "highlight", "target": "work[4][3]"}, {"delay": 0.4, "value": "\"var\"(x) = 6 / (4 - 1) = 6 / 3 = 2", "action": "set", "target": "formula[0]"}], "say": {"en": "They add up to six. Six divided by n minus one, which is three, gives a variance of two.", "hi": "इनका sum 6 है। 6 को n minus 1 से, यानी 3 से divide करने पर variance 2 आता है।", "te": "వీటి sum 6. 6 ను n minus 1 తో, అంటే 3 తో divide చేస్తే variance 2."}}, {"do": [{"action": "reset", "target": "work"}, {"value": "\"cov\"(x, y) = 1 / (n - 1) sum_(i=1)^n tilde(x)_i tilde(y)_i", "action": "set", "target": "formula[0]"}], "say": {"en": "Covariance follows the same recipe, but instead of squaring, we multiply x tilde by y tilde for each point.", "hi": "Covariance का method भी same है, लेकिन square करने की जगह हर point के लिए x tilde को y tilde से multiply करते हैं।", "te": "Covariance కూడా same method, కానీ square చేయడానికి బదులు ప్రతి point కు x tilde ను y tilde తో multiply చేస్తాం."}}, {"do": [{"delay": 0.05, "value": 2, "action": "set", "target": "work[0][4]"}, {"delay": 0.3, "value": 0, "action": "set", "target": "work[1][4]"}, {"delay": 0.55, "value": -1, "action": "set", "target": "work[2][4]"}, {"delay": 0.8, "value": 2, "action": "set", "target": "work[3][4]"}], "say": {"en": "Minus two times minus one is two. Zero times zero is zero. One times minus one is minus one. One times two is two.", "hi": "Minus 2 into minus 1 यानी 2। 0 into 0 यानी 0। 1 into minus 1 यानी minus 1। 1 into 2 यानी 2।", "te": "Minus 2 into minus 1 అంటే 2. 0 into 0 అంటే 0. 1 into minus 1 అంటే minus 1. 1 into 2 అంటే 2."}}, {"do": [{"value": 3, "action": "set", "target": "work[4][4]"}, {"delay": 0.2, "action": "highlight", "target": "work[4][4]"}, {"delay": 0.4, "value": "\"cov\"(x, y) = 3 / (4 - 1) = 3 / 3 = 1", "action": "set", "target": "formula[0]"}], "say": {"en": "The products add up to three, and three divided by three gives a covariance of one.", "hi": "इन products का sum 3 है, और 3 divided by 3 यानी covariance 1।", "te": "ఈ products యొక్క sum 3. 3 divided by 3 అంటే covariance 1."}}, {"do": [{"action": "reset", "target": "work"}], "say": {"en": "It is positive, which tells us that when x is above its mean, y tends to be above its mean as well.", "hi": "यह positive है। यानी जब x अपने mean से above होता है, तो y भी अपने mean से above होता है।", "te": "ఇది positive. అంటే x తన mean కంటే above ఉన్నప్పుడు, y కూడా తన mean కంటే above ఉంటుంది."}}, {"do": [{"delay": 0.1, "value": 1, "action": "set", "target": "work[0][5]"}, {"delay": 0.25, "value": 0, "action": "set", "target": "work[1][5]"}, {"delay": 0.4, "value": 1, "action": "set", "target": "work[2][5]"}, {"delay": 0.55, "value": 4, "action": "set", "target": "work[3][5]"}, {"delay": 0.7, "value": 6, "action": "set", "target": "work[4][5]"}, {"delay": 0.75, "action": "highlight", "target": "work[4][5]"}, {"delay": 0.8, "value": "\"var\"(y) = 6 / 3 = 2", "action": "set", "target": "formula[0]"}], "say": {"en": "Last, the variance of y. The squares are one, zero, one and four, which add up to six, so it is also two.", "hi": "Last में y का variance। Squares हैं 1, 0, 1 और 4। इनका sum 6 है, तो यह भी 2 है।", "te": "Last గా y యొక్క variance. Squares 1, 0, 1, 4. వీటి sum 6, కాబట్టి ఇది కూడా 2."}}, {"do": [{"action": "mark", "target": "work[4]"}, {"value": "C = mat(\"var\"(x), \"cov\"(x, y); \"cov\"(x, y), \"var\"(y)) = mat(2, 1; 1, 2)", "action": "set", "target": "formula[0]"}], "say": {"en": "Putting the three numbers in their places gives the covariance matrix: two, one, one, two.", "hi": "तीनों numbers को उनकी places पर रखने से covariance matrix मिलता है: 2, 1, 1, 2।", "te": "ఈ three numbers ను వాటి places లో పెడితే covariance matrix వస్తుంది: 2, 1, 1, 2."}}]}, {"id": "eigenvalues", "steps": [{"do": [{"text": "Step 3 of 6: eigenvalues", "action": "replace", "target": "heading"}, {"action": "hide", "target": "work"}, {"value": "C = mat(2, 1; 1, 2)", "action": "set", "target": "formula[0]"}, {"delay": 0.3, "action": "show", "target": "eig"}], "say": {"en": "Step three. We want the directions in which the data spreads the most. Those directions are the eigenvectors of C, and the spread along each one is its eigenvalue.", "hi": "Step 3. हमें वे directions चाहिए जिनमें data maximum spread है। वे directions, C के eigenvectors हैं, और हर direction का spread उसका eigenvalue है।", "te": "Step 3. Data ఏ directions లో maximum spread అయ్యిందో కావాలి. ఆ directions, C యొక్క eigenvectors. ప్రతి direction లో ఉన్న spread దాని eigenvalue."}}, {"do": [{"action": "highlight", "target": "eig[0]"}], "say": {"en": "This equation defines them. A vector v is an eigenvector if multiplying it by C only stretches it, without turning it. Lambda is how much it is stretched.", "hi": "यह equation उन्हें define करती है। अगर C से multiply करने पर vector v rotate न हो, only stretch हो, तो वह eigenvector है। Lambda बताता है कि वह कितना stretch हुआ।", "te": "ఈ equation వాటిని define చేస్తుంది. C తో multiply చేసినప్పుడు ఒక vector v rotate అవ్వకుండా only stretch అయితే, అది eigenvector. ఎంత stretch అయ్యిందో lambda చెబుతుంది."}}, {"do": [{"action": "reveal", "target": "eig[1]"}, {"action": "highlight", "target": "eig[1]"}], "say": {"en": "Such a v exists only when the determinant of C minus lambda times I is zero. I is the identity matrix, with ones on its diagonal.", "hi": "ऐसा v तभी exist करता है जब C minus lambda I का determinant zero हो। I identity matrix है, जिसके diagonal पर ones होते हैं।", "te": "C minus lambda I యొక్క determinant zero అయినప్పుడు మాత్రమే అలాంటి v exist అవుతుంది. I అంటే identity matrix, దాని diagonal లో ones ఉంటాయి."}}, {"do": [{"action": "reveal", "target": "eig[2]"}, {"action": "highlight", "target": "eig[2]"}], "say": {"en": "Subtracting lambda times I just takes lambda away from each diagonal entry of C.", "hi": "Lambda I subtract करने का मतलब है C की हर diagonal entry से lambda subtract करना।", "te": "Lambda I ను subtract చేయడం అంటే C యొక్క ప్రతి diagonal entry నుంచి lambda ను subtract చేయడమే."}}, {"do": [{"action": "reveal", "target": "eig[3]"}, {"action": "highlight", "target": "eig[3]"}], "say": {"en": "The determinant of a two by two matrix is the product of the diagonal, minus the product of the other two entries.", "hi": "2 by 2 matrix का determinant है diagonal entries का product, minus other two entries का product।", "te": "2 by 2 matrix యొక్క determinant అంటే diagonal entries product, minus other two entries product."}}, {"do": [{"action": "reveal", "target": "eig[4]"}, {"action": "highlight", "target": "eig[4]"}], "say": {"en": "Multiplying out, two minus lambda squared is four, minus four lambda, plus lambda squared. Taking away one leaves lambda squared, minus four lambda, plus three.", "hi": "Expand करने पर, 2 minus lambda whole square है 4, minus 4 lambda, plus lambda square। उसमें से 1 subtract करने पर आता है lambda square, minus 4 lambda, plus 3।", "te": "Expand చేస్తే, 2 minus lambda whole square అంటే 4, minus 4 lambda, plus lambda square. అందులోంచి 1 subtract చేస్తే lambda square, minus 4 lambda, plus 3 వస్తుంది."}}, {"do": [{"action": "reveal", "target": "eig[5]"}, {"action": "highlight", "target": "eig[5]"}], "say": {"en": "We need two numbers that multiply to three and add to four: three and one. So the eigenvalues are three and one.", "hi": "हमें two numbers चाहिए जिनका product 3 और sum 4 हो: 3 and 1। तो eigenvalues 3 and 1 हैं।", "te": "Product 3, sum 4 వచ్చే two numbers కావాలి: 3 and 1. కాబట్టి eigenvalues 3 and 1."}}, {"do": [{"value": "C = mat(2, 1; 1, 2) quad quad lambda_1 + lambda_2 = 3 + 1 = 4 = 2 + 2", "action": "set", "target": "formula[0]"}], "say": {"en": "Always check: the eigenvalues must add up to the sum of the diagonal of C. Three plus one is four, and two plus two is four.", "hi": "Always check करें: eigenvalues का sum, C के diagonal के sum के equal होना चाहिए। 3 plus 1 यानी 4, और 2 plus 2 भी 4।", "te": "Always check చేయండి: eigenvalues యొక్క sum, C యొక్క diagonal sum కు equal కావాలి. 3 plus 1 అంటే 4, 2 plus 2 కూడా 4."}}, {"do": [{"action": "reset", "target": "eig"}, {"value": "C = mat(2, 1; 1, 2) quad quad lambda_1 = 3 quad quad lambda_2 = 1", "action": "set", "target": "formula[0]"}], "say": {"en": "We name the larger one lambda one, because the largest eigenvalue belongs to the direction with the most spread.", "hi": "Larger one को हम lambda 1 कहते हैं, क्योंकि largest eigenvalue उस direction का होता है जिसमें maximum spread है।", "te": "Larger one కు lambda 1 అని name ఇస్తాం, ఎందుకంటే largest eigenvalue, maximum spread ఉన్న direction కు belong అవుతుంది."}}]}, {"id": "eigenvectors", "steps": [{"do": [{"text": "Step 4 of 6: eigenvectors", "action": "replace", "target": "heading"}, {"action": "hide", "target": "eig"}, {"action": "show", "target": "vec"}], "say": {"en": "Step four. Each eigenvalue has its own direction. To find the first, put lambda equals three back into C minus lambda I, times v, equals zero.", "hi": "Step 4. हर eigenvalue की अपनी direction होती है। First one find करने के लिए, C minus lambda I, into v, equals 0 में lambda equals 3 substitute करें।", "te": "Step 4. ప్రతి eigenvalue కు దాని own direction ఉంటుంది. First one find చేయడానికి, C minus lambda I, into v, equals 0 లో lambda equals 3 substitute చేయండి."}}, {"do": [{"action": "reveal", "target": "vec[1]"}, {"action": "highlight", "target": "vec[1]"}], "say": {"en": "Two minus three is minus one on the diagonal, and the ones stay where they are.", "hi": "Diagonal पर 2 minus 3 यानी minus 1 आता है, और ones वैसे ही रहते हैं।", "te": "Diagonal లో 2 minus 3 అంటే minus 1 వస్తుంది. Ones అలాగే ఉంటాయి."}}, {"do": [{"action": "reveal", "target": "vec[2]"}, {"action": "highlight", "target": "vec[2]"}], "say": {"en": "The top row says minus v x plus v y equals zero, so v y equals v x. The bottom row says the same thing, which is normal.", "hi": "Top row कहती है minus v x plus v y equals 0, तो v y equals v x। Bottom row भी same कहती है, और यह normal है।", "te": "Top row ప్రకారం minus v x plus v y equals 0, కాబట్టి v y equals v x. Bottom row కూడా same చెబుతుంది, అది normal."}}, {"do": [{"action": "reveal", "target": "vec[3]"}, {"action": "highlight", "target": "vec[3]"}], "say": {"en": "Any vector with equal parts works, so take one, one. PCA wants a direction of length one, and the length of one, one is root two, so we divide by root two.", "hi": "Equal parts वाला कोई भी vector work करेगा, तो 1, 1 लेते हैं। PCA को length 1 वाली direction चाहिए। 1, 1 की length root 2 है, इसलिए root 2 से divide करते हैं।", "te": "Equal parts ఉన్న ఏ vector అయినా work అవుతుంది, కాబట్టి 1, 1 తీసుకుందాం. PCA కు length 1 ఉన్న direction కావాలి. 1, 1 యొక్క length root 2, కాబట్టి root 2 తో divide చేస్తాం."}}, {"do": [{"action": "trace", "target": "cloud.pc1"}], "say": {"en": "On the plot, that is the diagonal line through the origin. It is the first principal component.", "hi": "Plot पर यह origin से through जाने वाली diagonal line है। यही first principal component है।", "te": "Plot లో అది origin through వెళ్ళే diagonal line. అదే first principal component."}}, {"do": [{"action": "hide", "target": "vec"}, {"action": "show", "target": "vec2"}, {"delay": 0.5, "action": "highlight", "target": "vec2[1]"}], "say": {"en": "For the second, use lambda equals one. Two minus one is one, so every entry of the matrix is one.", "hi": "Second one के लिए lambda equals 1 use करें। 2 minus 1 यानी 1, तो matrix की हर entry 1 है।", "te": "Second one కోసం lambda equals 1 use చేయండి. 2 minus 1 అంటే 1, కాబట్టి matrix లోని ప్రతి entry 1."}}, {"do": [{"action": "reveal", "target": "vec2[3]"}, {"delay": 0.4, "action": "highlight", "target": "vec2[3]"}, {"delay": 0.5, "action": "trace", "target": "cloud.pc2"}], "say": {"en": "Now v x plus v y equals zero, so v y is minus v x. Take minus one, one, and divide by root two again.", "hi": "अब v x plus v y equals 0, तो v y equals minus v x। Minus 1, 1 लेते हैं और again root 2 से divide करते हैं।", "te": "ఇప్పుడు v x plus v y equals 0, కాబట్టి v y equals minus v x. Minus 1, 1 తీసుకుని again root 2 తో divide చేస్తాం."}}, {"do": [{"action": "reveal", "target": "vec2[4]"}, {"action": "highlight", "target": "vec2[4]"}], "say": {"en": "Check that the two are perpendicular: their dot product is minus one plus one, over two, which is zero. For a covariance matrix this must always happen.", "hi": "Check करें कि दोनों perpendicular हैं: इनका dot product है minus 1 plus 1, by 2, यानी zero। Covariance matrix के लिए यह always होना चाहिए।", "te": "ఈ రెండూ perpendicular అని check చేయండి: వాటి dot product, minus 1 plus 1, by 2, అంటే zero. Covariance matrix కు ఇది always జరగాలి."}}]}, {"id": "project", "steps": [{"do": [{"text": "Step 5 of 6: project the data", "action": "replace", "target": "heading"}, {"action": "hide", "target": "vec2"}, {"action": "dim", "target": "cloud.pc2"}, {"action": "mark", "target": "cloud.pc1"}, {"value": "bold(v)_1 = 1 / sqrt(2) vec(1, 1) quad quad lambda_1 = 3", "action": "set", "target": "formula[0]"}], "say": {"en": "Step five. To go from two features to one, we keep the first component and drop the second, because the second has the smaller eigenvalue.", "hi": "Step 5. Two features से one पर reduce करने के लिए, हम first component keep करते हैं और second drop करते हैं, क्योंकि second का eigenvalue smaller है।", "te": "Step 5. Two features నుంచి one కు reduce చేయడానికి, first component ను keep చేసి second ను drop చేస్తాం, ఎందుకంటే second కు smaller eigenvalue ఉంది."}}, {"do": [{"action": "show", "target": "proj"}, {"delay": 0.5, "action": "highlight", "target": "proj[0]"}], "say": {"en": "The new value of each point, called z, is the dot product of v one with the centred point. That means add x tilde and y tilde, and divide by root two.", "hi": "हर point की new value को z कहते हैं। यह v 1 और centred point का dot product है। यानी x tilde और y tilde add करें, और root 2 से divide करें।", "te": "ప్రతి point యొక్క new value ను z అంటాం. అది v 1 కు, centred point కు మధ్య dot product. అంటే x tilde, y tilde add చేసి root 2 తో divide చేయడం."}}, {"do": [{"action": "reveal", "target": "proj[1]"}, {"action": "highlight", "target": "proj[1]"}, {"at": [-1.5, -1.5], "delay": 0.5, "action": "move_to", "target": "cloud.a"}], "say": {"en": "For A, minus two plus minus one is minus three. Root two is about one point four one four, so z is minus two point one two.", "hi": "A के लिए, minus 2 plus minus 1 यानी minus 3। Root 2 approximately 1.414 है, तो z equals minus 2.12।", "te": "A కోసం, minus 2 plus minus 1 అంటే minus 3. Root 2 approximately 1.414, కాబట్టి z equals minus 2.12."}}, {"do": [{"action": "reveal", "target": "proj[2]"}, {"action": "highlight", "target": "proj[2]"}, {"at": [0, 0], "delay": 0.5, "action": "move_to", "target": "cloud.c"}], "say": {"en": "B is at the origin, so its z is zero. For C, one plus minus one is also zero.", "hi": "B origin पर है, तो उसका z zero है। C के लिए, 1 plus minus 1 भी zero है।", "te": "B origin దగ్గర ఉంది, కాబట్టి దాని z zero. C కోసం, 1 plus minus 1 కూడా zero."}}, {"do": [{"action": "reveal", "target": "proj[3]"}, {"action": "highlight", "target": "proj[3]"}, {"at": [1.5, 1.5], "delay": 0.5, "action": "move_to", "target": "cloud.d"}], "say": {"en": "For D, one plus two is three, and three over root two is two point one two.", "hi": "D के लिए, 1 plus 2 यानी 3, और 3 by root 2 यानी 2.12।", "te": "D కోసం, 1 plus 2 అంటే 3. 3 by root 2 అంటే 2.12."}}, {"do": [{"action": "reset", "target": "proj"}], "say": {"en": "On the plot each point has dropped straight onto the line. These four numbers are the data in one dimension.", "hi": "Plot पर हर point straight line पर drop हो गया है। ये four numbers, one dimension में हमारा data हैं।", "te": "Plot లో ప్రతి point straight గా line మీదకు drop అయ్యింది. ఈ four numbers, one dimension లో మన data."}}]}, {"id": "kept", "steps": [{"do": [{"text": "Step 6 of 6: variance kept", "action": "replace", "target": "heading"}, {"action": "hide", "target": "proj"}, {"action": "hide", "target": "formula"}, {"action": "show", "target": "keep"}], "say": {"en": "Step six. How much did we lose by dropping the second component? The eigenvalues answer that directly.", "hi": "Step 6. Second component drop करने से हमने कितना lose किया? Eigenvalues इसका direct answer देते हैं।", "te": "Step 6. Second component ను drop చేయడం వల్ల ఎంత lose అయ్యాం? దానికి eigenvalues directly answer ఇస్తాయి."}}, {"do": [{"action": "highlight", "target": "keep[0]"}], "say": {"en": "Each eigenvalue is the variance along its component, so the total variance is three plus one, which is four.", "hi": "हर eigenvalue अपने component के along का variance है। तो total variance है 3 plus 1, यानी 4।", "te": "ప్రతి eigenvalue, దాని component along ఉన్న variance. కాబట్టి total variance, 3 plus 1, అంటే 4."}}, {"do": [{"action": "reveal", "target": "keep[1]"}, {"action": "highlight", "target": "keep[1]"}], "say": {"en": "The first component holds three of those four, so it keeps seventy-five percent.", "hi": "उस 4 में से 3 first component के पास है, तो वह 75 percent retain करता है।", "te": "ఆ 4 లో 3 first component దగ్గర ఉంది, కాబట్టి అది 75 percent ను retain చేస్తుంది."}}, {"do": [{"action": "reveal", "target": "keep[2]"}, {"action": "highlight", "target": "keep[2]"}], "say": {"en": "You can confirm this from the z values. Three over root two, squared, is nine over two, or four point five. So the squares add to nine, and nine over three is three: the first eigenvalue.", "hi": "इसे z values से confirm कर सकते हैं। 3 by root 2 का square है 9 by 2, यानी 4.5। तो squares का sum 9 है, और 9 by 3 यानी 3: यही first eigenvalue है।", "te": "దీన్ని z values తో confirm చేయవచ్చు. 3 by root 2 యొక్క square అంటే 9 by 2, అంటే 4.5. కాబట్టి squares యొక్క sum 9. 9 by 3 అంటే 3, అదే first eigenvalue."}}, {"do": [{"action": "reset", "target": "keep"}, {"action": "show", "target": "note"}], "say": {"en": "So one number per point now carries seventy-five percent of what two numbers carried.", "hi": "यानी अब हर point का one number, उस information का 75 percent carry कर रहा है जो पहले two numbers में थी।", "te": "అంటే ఇప్పుడు ప్రతి point కు one number, two numbers లో ఉన్న information లో 75 percent ను carry చేస్తోంది."}}]}, {"id": "recap", "steps": [{"do": [{"text": "PCA in six steps", "action": "replace", "target": "heading"}, {"action": "hide", "target": "keep"}, {"action": "hide", "target": "cloud"}, {"action": "hide", "target": "note"}, {"action": "show", "target": "roadmap"}, {"delay": 0.5, "action": "reset", "target": "roadmap"}], "say": {"en": "To do this in an exam, write down the same six steps.", "hi": "Exam में यह solve करने के लिए, यही six steps लिखें।", "te": "Exam లో ఇది solve చేయడానికి, ఇవే six steps రాయండి."}}, {"do": [{"delay": 0.0, "action": "mark", "target": "roadmap[0]"}, {"delay": 0.3, "action": "mark", "target": "roadmap[1]"}, {"delay": 0.65, "action": "mark", "target": "roadmap[2]"}], "say": {"en": "Centre the data by subtracting the mean. Build the covariance matrix, dividing by n minus one. Solve the determinant equation for the eigenvalues.", "hi": "Mean subtract करके data को centre करें। n minus 1 से divide करते हुए covariance matrix build करें। Determinant equation solve करके eigenvalues find करें।", "te": "Mean ను subtract చేసి data ను centre చేయండి. n minus 1 తో divide చేస్తూ covariance matrix build చేయండి. Determinant equation solve చేసి eigenvalues find చేయండి."}}, {"do": [{"delay": 0.0, "action": "mark", "target": "roadmap[3]"}, {"delay": 0.4, "action": "mark", "target": "roadmap[4]"}, {"delay": 0.7, "action": "mark", "target": "roadmap[5]"}], "say": {"en": "Then find each eigenvector and scale it to length one. Project the centred data onto the largest. And report the share of variance kept.", "hi": "फिर हर eigenvector find करें और उसे length 1 पर scale करें। Centred data को largest eigenvector पर project करें। और report करें कि कितना variance retain हुआ।", "te": "తర్వాత ప్రతి eigenvector find చేసి దాన్ని length 1 కు scale చేయండి. Centred data ను largest eigenvector మీద project చేయండి. Last గా, ఎంత variance retain అయ్యిందో report చేయండి."}}]}], "objects": [{"id": "heading", "text": "PCA, computed by hand", "type": "text", "region": "title"}, {"id": "roadmap", "rows": [[1, "Centre the data", "spread is measured from the mean"], [2, "Covariance matrix", "how the features vary together"], [3, "Eigenvalues", "how much spread each direction has"], [4, "Eigenvectors", "which directions those are"], [5, "Project", "swap two features for one"], [6, "Variance kept", "how much information survived"]], "type": "table", "region": "center", "columns": ["step", "what we do", "why"]}, {"id": "data", "rows": [["A", 2, 2, "", ""], ["B", 4, 3, "", ""], ["C", 5, 2, "", ""], ["D", 5, 5, "", ""]], "type": "table", "region": "left", "columns": ["point", "x", "y", "x − 4", "y − 3"]}, {"x": {"max": 6, "min": -3, "label": "x"}, "y": {"max": 6, "min": -3, "label": "y"}, "id": "cloud", "type": "plot", "equal": true, "curves": [{"fn": "x", "id": "pc1", "label": "PC1", "visible": false}, {"fn": "-x", "id": "pc2", "label": "PC2", "visible": false}], "points": [{"at": [2, 2], "id": "a", "label": "A"}, {"at": [4, 3], "id": "b", "label": "B"}, {"at": [5, 2], "id": "c", "label": "C"}, {"at": [5, 5], "id": "d", "label": "D"}], "region": "right"}, {"id": "formula", "type": "math", "lines": ["overline(x) = 1 / n sum_(i=1)^n x_i"], "region": "bottom"}, {"id": "work", "rows": [["A", -2, -1, "", "", ""], ["B", 0, 0, "", "", ""], ["C", 1, -1, "", "", ""], ["D", 1, 2, "", "", ""], ["sum", "", "", "", "", ""]], "type": "table", "region": "left", "columns": ["point", "x̃", "ỹ", "x̃²", "x̃ · ỹ", "ỹ²"]}, {"id": "eig", "type": "math", "lines": ["C bold(v) = lambda bold(v)", "det(C - lambda I) = 0", "det mat(2 - lambda, 1; 1, 2 - lambda) = 0", "(2 - lambda)(2 - lambda) - 1 dot 1 = 0", "lambda^2 - 4 lambda + 3 = 0", "(lambda - 3)(lambda - 1) = 0 quad => quad lambda = 3 \" or \" 1"], "region": "left"}, {"id": "vec", "type": "math", "lines": ["(C - 3 I) bold(v) = bold(0)", "mat(-1, 1; 1, -1) vec(v_x, v_y) = vec(0, 0)", "-v_x + v_y = 0 quad => quad v_y = v_x", "bold(v)_1 = 1 / sqrt(2) vec(1, 1) approx vec(0.707, 0.707)"], "region": "left"}, {"id": "vec2", "type": "math", "lines": ["(C - 1 I) bold(v) = bold(0)", "mat(1, 1; 1, 1) vec(v_x, v_y) = vec(0, 0)", "v_x + v_y = 0 quad => quad v_y = -v_x", "bold(v)_2 = 1 / sqrt(2) vec(-1, 1)", "bold(v)_1 dot bold(v)_2 = (-1 + 1) / 2 = 0"], "shown": 2, "region": "left"}, {"id": "proj", "type": "math", "lines": ["z_i = bold(v)_1 dot tilde(bold(x))_i = (tilde(x)_i + tilde(y)_i) / sqrt(2)", "z_A = (-2 + (-1)) / sqrt(2) = (-3) / 1.414 = -2.12", "z_B = (0 + 0) / sqrt(2) = 0 quad quad z_C = (1 + (-1)) / sqrt(2) = 0", "z_D = (1 + 2) / sqrt(2) = 3 / 1.414 = 2.12"], "region": "left"}, {"id": "keep", "type": "math", "lines": ["\"total variance\" = lambda_1 + lambda_2 = 3 + 1 = 4", "\"kept by PC1\" = lambda_1 / (lambda_1 + lambda_2) = 3 / 4 = 75 \"%\"", "\"var\"(z) = (4.5 + 0 + 0 + 4.5) / 3 = 9 / 3 = 3 = lambda_1"], "region": "left"}, {"id": "note", "text": "Two features became one, and 75% of the variance survived.", "type": "text", "region": "bottom"}], "version": 1}', '[{"scene": "overview", "steps": 3, "seconds": 23, "opens_with": "Principal component analysis, అంటే PCA, చాలా related features ను కొన్ని new features తో replace చేస్తుంది, కానీ maximum "}, {"scene": "centre", "steps": 11, "seconds": 67, "opens_with": "ఇది మన data: A నుంచి D వరకు four points. ప్రతి point కు x, y అనే two features ఉన్నాయి."}, {"scene": "covariance", "steps": 13, "seconds": 86, "opens_with": "Step 2. ప్రతి feature ఎంత spread అయ్యిందో, రెండూ together move అవుతున్నాయో లేదో తెలియాలి. Covariance matrix లో exactly అ"}, {"scene": "eigenvalues", "steps": 9, "seconds": 73, "opens_with": "Step 3. Data ఏ directions లో maximum spread అయ్యిందో కావాలి. ఆ directions, C యొక్క eigenvectors. ప్రతి direction లో ఉన్న"}, {"scene": "eigenvectors", "steps": 8, "seconds": 60, "opens_with": "Step 4. ప్రతి eigenvalue కు దాని own direction ఉంటుంది. First one find చేయడానికి, C minus lambda I, into v, equals 0 లో "}, {"scene": "project", "steps": 6, "seconds": 40, "opens_with": "Step 5. Two features నుంచి one కు reduce చేయడానికి, first component ను keep చేసి second ను drop చేస్తాం, ఎందుకంటే second"}, {"scene": "kept", "steps": 5, "seconds": 35, "opens_with": "Step 6. Second component ను drop చేయడం వల్ల ఎంత lose అయ్యాం? దానికి eigenvalues directly answer ఇస్తాయి."}, {"scene": "recap", "steps": 3, "seconds": 25, "opens_with": "Exam లో ఇది solve చేయడానికి, ఇవే six steps రాయండి."}]', 4, '2026-10-04 03:46:54.898377+00', '2026-10-04 03:49:30.341827+00', '2026-10-04 03:49:56.685046+00', 'ml') on conflict (id) do nothing;
insert into videos (id, user_id, title, language, speaker, voiced, captions, status, progress, error, seconds, steps, characters, is_public, script, outline, views, created_at, finished_at, published_at, subject) values ('c85158038e54', '52061686-0664-40b2-8dd3-99457b33ce76', 'Banker''s algorithm, worked step by step', 'te', 'Vasudha', true, true, 'done', 'finished', NULL, 433.367, 53, 4838, true, '{"version": 1, "title": "OS: Banker''s algorithm, worked step by step", "objects": [{"id": "heading", "type": "text", "region": "title", "text": "Banker''s algorithm: avoiding deadlock"}, {"id": "roadmap", "type": "table", "region": "center", "columns": ["stage", "what we find", "why"], "rows": [[1, "Need matrix", "what each process may still ask for"], [2, "Available", "what is free right now"], [3, "Safety check", "an order in which every process can finish"], [4, "A new request", "grant it only if the state stays safe"]]}, {"id": "mat", "type": "table", "region": "left", "columns": ["process", "Allocation", "Max", "Need", "Finish"], "rows": [["P0", "0 1 0", "7 5 3", "", "F"], ["P1", "2 0 0", "3 2 2", "", "F"], ["P2", "3 0 2", "9 0 2", "", "F"], ["P3", "2 1 1", "2 2 2", "", "F"], ["P4", "0 0 2", "4 3 3", "", "F"]]}, {"id": "status", "type": "text", "region": "bottom", "text": "Total: A = 10, B = 5, C = 7"}, {"id": "needeq", "type": "math", "region": "right", "lines": ["\"Need\" = \"Max\" - \"Allocation\"", "P_0 : (7, 5, 3) - (0, 1, 0) = (7, 4, 3)", "P_1 : (3, 2, 2) - (2, 0, 0) = (1, 2, 2)", "P_2, P_3, P_4 : (6, 0, 0), (0, 1, 1), (4, 3, 1)"]}, {"id": "avail", "type": "math", "region": "right", "lines": ["\"Available\" = \"Total\" - sum \"Allocation\"", "sum \"Allocation\" = (7, 2, 5)", "(10, 5, 7) - (7, 2, 5) = (3, 3, 2)"]}, {"id": "rule", "type": "math", "region": "right", "lines": ["\"Work\" = \"Available\" = (3, 3, 2)", "\"if\" \"Need\"_i <= \"Work\" :", "\"Work\" = \"Work\" + \"Allocation\"_i , quad \"Finish\"_i = T"]}, {"id": "log", "type": "table", "region": "right", "columns": ["check", "Need ≤ Work?", "Work after"], "rows": [["P0", "7 4 3 ≤ 3 3 2: no", ""]]}, {"id": "req", "type": "math", "region": "right", "lines": ["\"Request\"_1 = (1, 0, 2)", "(1, 0, 2) <= \"Need\"_1 = (1, 2, 2) quad \"yes\"", "(1, 0, 2) <= \"Available\" = (3, 3, 2) quad \"yes\"", "\"Available\" = (3, 3, 2) - (1, 0, 2) = (2, 3, 0)", "\"Allocation\"_1 = (2, 0, 0) + (1, 0, 2) = (3, 0, 2)"]}, {"id": "log2", "type": "table", "region": "right", "columns": ["check", "Need ≤ Work?", "Work after"], "rows": [["P0", "7 4 3 ≤ 2 3 0: no", ""]]}], "scenes": [{"id": "overview", "steps": [{"say": {"en": "Banker''s algorithm decides whether the operating system can safely give resources to a process, without ever reaching deadlock.", "te": "Banker''s algorithm అంటే, deadlock రాకుండా, ఒక process కు resources ఇవ్వడం safe అవునా కాదా అని operating system decide చేసే method."}, "do": [{"action": "write", "target": "heading"}]}, {"say": {"en": "It is named after a bank, which lends money only if it can still pay every customer back in some order.", "te": "దీనికి bank పేరు ఎందుకంటే, ఒక bank తన customers అందరికీ ఏదో ఒక order లో pay చేయగలిగితేనే loan ఇస్తుంది."}, "do": []}, {"say": {"en": "We will work one exam problem through four stages.", "te": "మనం ఒక exam problem ను four stages లో solve చేస్తాం."}, "do": [{"action": "show", "target": "roadmap"}]}, {"say": {"en": "First the need matrix, then the available vector, then the safety check, and last a new request.", "te": "First need matrix, తర్వాత available vector, తర్వాత safety check, last గా ఒక new request."}, "do": [{"action": "highlight", "target": "roadmap[0]"}, {"action": "highlight", "target": "roadmap[1]", "delay": 0.25}, {"action": "highlight", "target": "roadmap[2]", "delay": 0.5}, {"action": "highlight", "target": "roadmap[3]", "delay": 0.75}]}]}, {"id": "problem", "steps": [{"say": {"en": "Here is the problem. There are five processes, P0 to P4, and three resource types, A, B and C.", "te": "ఇది problem. ఇక్కడ P0 నుంచి P4 వరకు five processes, A, B, C అనే three resource types ఉన్నాయి."}, "do": [{"action": "replace", "target": "heading", "text": "The problem"}, {"action": "hide", "target": "roadmap"}, {"action": "show", "target": "mat", "delay": 0.2}]}, {"say": {"en": "The system has 10 instances of A, 5 of B and 7 of C in total.", "te": "System లో total గా A వి 10, B వి 5, C వి 7 instances ఉన్నాయి."}, "do": [{"action": "write", "target": "status"}]}, {"say": {"en": "The allocation column is what each process holds right now. P0 holds zero A, one B and zero C.", "te": "Allocation column అంటే ప్రతి process ఇప్పుడు hold చేస్తున్న resources. P0 దగ్గర zero A, one B, zero C ఉన్నాయి."}, "do": [{"action": "highlight", "target": "mat.Allocation"}, {"action": "highlight", "target": "mat[0][1]", "delay": 0.55}]}, {"say": {"en": "The max column is the most each process may ever ask for. P0 may need up to seven A, five B and three C.", "te": "Max column అంటే ప్రతి process ever అడగగలిగే maximum. P0 కు up to seven A, five B, three C అవసరం కావచ్చు."}, "do": [{"action": "highlight", "target": "mat.Max"}, {"action": "highlight", "target": "mat[0][2]", "delay": 0.55}]}, {"say": {"en": "Every process declares its max in advance. That is what lets the system plan ahead.", "te": "ప్రతి process తన max ను advance గా declare చేస్తుంది. అందుకే system advance గా plan చేయగలదు."}, "do": [{"action": "reset", "target": "mat"}]}]}, {"id": "need", "steps": [{"say": {"en": "The first question is how much more each process can still ask for. That is called its need.", "te": "First question: ప్రతి process ఇంకా ఎంత more అడగగలదు? దాన్నే need అంటారు."}, "do": [{"action": "replace", "target": "heading", "text": "Stage 1 of 4: the need matrix"}, {"action": "show", "target": "needeq"}]}, {"say": {"en": "Need is max minus allocation: the most it may want, minus what it already holds.", "te": "Need అంటే max minus allocation: అది want చేసే maximum లో నుంచి already hold చేస్తున్నది minus చేస్తాం."}, "do": [{"action": "highlight", "target": "needeq[0]"}]}, {"say": {"en": "For P0, seven five three minus zero one zero gives seven four three.", "te": "P0 కు, seven five three minus zero one zero చేస్తే seven four three వస్తుంది."}, "do": [{"action": "reveal", "target": "needeq[1]"}, {"action": "highlight", "target": "mat[0]"}, {"action": "set", "target": "mat[0][3]", "value": "7 4 3", "delay": 0.5}]}, {"say": {"en": "For P1, three two two minus two zero zero gives one two two.", "te": "P1 కు, three two two minus two zero zero చేస్తే one two two వస్తుంది."}, "do": [{"action": "reveal", "target": "needeq[2]"}, {"action": "highlight", "target": "mat[1]"}, {"action": "set", "target": "mat[1][3]", "value": "1 2 2", "delay": 0.5}]}, {"say": {"en": "The same subtraction for P2, P3 and P4 gives six zero zero, zero one one, and four three one.", "te": "అదే subtraction P2, P3, P4 కు చేస్తే six zero zero, zero one one, four three one వస్తాయి."}, "do": [{"action": "reveal", "target": "needeq[3]"}, {"action": "highlight", "target": "mat[2..5]"}, {"action": "set", "target": "mat[2][3]", "value": "6 0 0", "delay": 0.3}, {"action": "set", "target": "mat[3][3]", "value": "0 1 1", "delay": 0.5}, {"action": "set", "target": "mat[4][3]", "value": "4 3 1", "delay": 0.7}]}, {"say": {"en": "A quick check: no need can be negative, because no process holds more than its max.", "te": "ఒక quick check: ఏ need కూడా negative కాకూడదు, ఎందుకంటే ఏ process కూడా తన max కంటే more hold చేయదు."}, "do": [{"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Need"}]}]}, {"id": "available", "steps": [{"say": {"en": "Next, how much of each resource is free right now. This is the available vector.", "te": "Next, ఇప్పుడు ప్రతి resource ఎంత free గా ఉంది? దీన్నే available vector అంటారు."}, "do": [{"action": "replace", "target": "heading", "text": "Stage 2 of 4: what is available"}, {"action": "hide", "target": "needeq"}, {"action": "show", "target": "avail", "delay": 0.2}]}, {"say": {"en": "Available is the total minus everything that is already allocated.", "te": "Available అంటే total minus already allocate అయినవి అన్నీ."}, "do": [{"action": "highlight", "target": "avail[0]"}]}, {"say": {"en": "Add down the allocation column. For A, zero plus two plus three plus two plus zero is seven. B adds to two, and C to five.", "te": "Allocation column ను add చేద్దాం. A కు zero plus two plus three plus two plus zero, seven. B add చేస్తే two, C add చేస్తే five."}, "do": [{"action": "reveal", "target": "avail[1]"}, {"action": "highlight", "target": "mat.Allocation"}]}, {"say": {"en": "Ten five seven minus seven two five leaves three three two free.", "te": "Ten five seven minus seven two five చేస్తే three three two free గా ఉంటాయి."}, "do": [{"action": "reveal", "target": "avail[2]"}, {"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Need"}, {"action": "replace", "target": "status", "text": "Total (10, 5, 7)    Available (3, 3, 2)", "delay": 0.5}]}]}, {"id": "safety", "steps": [{"say": {"en": "Now the main question: is there an order in which every process can finish? If there is, the state is safe.", "te": "ఇప్పుడు main question: ప్రతి process finish అయ్యే order ఏదైనా ఉందా? ఉంటే, ఆ state safe."}, "do": [{"action": "replace", "target": "heading", "text": "Stage 3 of 4: the safety check"}, {"action": "hide", "target": "avail"}, {"action": "show", "target": "rule", "delay": 0.2}]}, {"say": {"en": "We start with work equal to available, three three two, and every process marked not finished.", "te": "Work = available, అంటే three three two తో start చేస్తాం, ప్రతి process not finished గా ఉంటుంది."}, "do": [{"action": "highlight", "target": "rule[0]"}, {"action": "highlight", "target": "mat.Finish"}, {"action": "replace", "target": "status", "text": "Work = (3, 3, 2)", "delay": 0.5}]}, {"say": {"en": "The rule: if a process''s need fits in work, it can run to the end and then give back everything it holds.", "te": "Rule: ఒక process need, work లో fit అయితే, అది end వరకు run అయి, తను hold చేసినవన్నీ return చేస్తుంది."}, "do": [{"action": "reveal", "target": "rule[1]"}, {"action": "highlight", "target": "rule[1]"}]}, {"say": {"en": "So work grows by that process''s allocation, and we mark it finished.", "te": "కాబట్టి work కు ఆ process allocation add అవుతుంది, దాన్ని finished గా mark చేస్తాం."}, "do": [{"action": "reveal", "target": "rule[2]"}, {"action": "highlight", "target": "rule[2]"}]}, {"say": {"en": "We scan from P0 to P4, and go back to the top until no process can move.", "te": "P0 నుంచి P4 వరకు scan చేస్తాం, ఏ process కూడా move చేయలేనంత వరకు మళ్ళీ top నుంచి start చేస్తాం."}, "do": [{"action": "reset", "target": "rule"}, {"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Need"}]}, {"say": {"en": "P0 needs seven four three, but work has only three A. Seven does not fit in three, so P0 waits.", "te": "P0 కు seven four three need, కానీ work లో three A మాత్రమే. Seven, three లో fit కాదు, కాబట్టి P0 wait చేస్తుంది."}, "do": [{"action": "hide", "target": "rule"}, {"action": "show", "target": "log"}, {"action": "highlight", "target": "mat[0]"}]}, {"say": {"en": "P1 needs one two two. One is at most three, two is at most three, and two is at most two, so it fits.", "te": "P1 కు one two two need. One, three కంటే less, two, three కంటే less, two, two కి equal, కాబట్టి fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[1]"}, {"action": "add_row", "target": "log", "values": ["P1", "1 2 2 ≤ 3 3 2: yes", ""]}]}, {"say": {"en": "P1 finishes and returns two zero zero. Work becomes three three two plus two zero zero, which is five three two.", "te": "P1 finish అయి two zero zero return చేస్తుంది. Work, three three two plus two zero zero, అంటే five three two."}, "do": [{"action": "set", "target": "mat[1][4]", "value": "T"}, {"action": "set", "target": "log[1][2]", "value": "5 3 2", "delay": 0.4}, {"action": "replace", "target": "status", "text": "Work = (5, 3, 2)    order: P1", "delay": 0.6}]}, {"say": {"en": "P2 needs six A, but work has five. It waits.", "te": "P2 కు six A need, కానీ work లో five మాత్రమే. అది wait చేస్తుంది."}, "do": [{"action": "highlight", "target": "mat[2]"}, {"action": "add_row", "target": "log", "values": ["P2", "6 0 0 ≤ 5 3 2: no", ""]}]}, {"say": {"en": "P3 needs zero one one, which fits in five three two.", "te": "P3 కు zero one one need, అది five three two లో fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[3]"}, {"action": "add_row", "target": "log", "values": ["P3", "0 1 1 ≤ 5 3 2: yes", ""]}]}, {"say": {"en": "P3 returns two one one, so work becomes seven four three.", "te": "P3 two one one return చేస్తుంది, కాబట్టి work seven four three అవుతుంది."}, "do": [{"action": "set", "target": "mat[3][4]", "value": "T"}, {"action": "set", "target": "log[3][2]", "value": "7 4 3", "delay": 0.3}, {"action": "replace", "target": "status", "text": "Work = (7, 4, 3)    order: P1, P3", "delay": 0.5}]}, {"say": {"en": "P4 needs four three one, which fits in seven four three.", "te": "P4 కు four three one need, అది seven four three లో fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[4]"}, {"action": "add_row", "target": "log", "values": ["P4", "4 3 1 ≤ 7 4 3: yes", ""]}]}, {"say": {"en": "P4 returns zero zero two, so work becomes seven four five.", "te": "P4 zero zero two return చేస్తుంది, కాబట్టి work seven four five అవుతుంది."}, "do": [{"action": "set", "target": "mat[4][4]", "value": "T"}, {"action": "set", "target": "log[4][2]", "value": "7 4 5", "delay": 0.3}, {"action": "replace", "target": "status", "text": "Work = (7, 4, 5)    order: P1, P3, P4", "delay": 0.5}]}, {"say": {"en": "Back to the top. P0 needs seven four three, and now that fits in seven four five.", "te": "మళ్ళీ top కు. P0 కు seven four three need, ఇప్పుడు అది seven four five లో fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[0]"}, {"action": "add_row", "target": "log", "values": ["P0", "7 4 3 ≤ 7 4 5: yes", ""]}]}, {"say": {"en": "P0 returns zero one zero, so work becomes seven five five.", "te": "P0 zero one zero return చేస్తుంది, కాబట్టి work seven five five అవుతుంది."}, "do": [{"action": "set", "target": "mat[0][4]", "value": "T"}, {"action": "set", "target": "log[5][2]", "value": "7 5 5", "delay": 0.3}, {"action": "replace", "target": "status", "text": "Work = (7, 5, 5)    order: P1, P3, P4, P0", "delay": 0.5}]}, {"say": {"en": "P2 needs six zero zero, which fits in seven five five. It returns three zero two, and work becomes ten five seven.", "te": "P2 కు six zero zero need, అది seven five five లో fit అవుతుంది. అది three zero two return చేస్తుంది, work ten five seven అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[2]"}, {"action": "add_row", "target": "log", "values": ["P2", "6 0 0 ≤ 7 5 5: yes", ""]}, {"action": "set", "target": "mat[2][4]", "value": "T", "delay": 0.5}, {"action": "set", "target": "log[6][2]", "value": "10 5 7", "delay": 0.6}]}, {"say": {"en": "Every process finished, so the state is safe. The safe sequence is P1, P3, P4, P0, P2.", "te": "ప్రతి process finish అయ్యింది, కాబట్టి ఈ state safe. Safe sequence: P1, P3, P4, P0, P2."}, "do": [{"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Finish"}, {"action": "replace", "target": "status", "text": "Safe sequence: P1 → P3 → P4 → P0 → P2", "delay": 0.3}]}, {"say": {"en": "Check: the final work, ten five seven, equals the total. Every resource came back, as it must.", "te": "Check: final work ten five seven, total కి equal. ప్రతి resource back వచ్చింది, అలాగే రావాలి."}, "do": [{"action": "highlight", "target": "log[6][2]"}]}, {"say": {"en": "Other orders can be safe too, such as P1, P3, P4, P2, P0. Any order where each need fits is accepted, so show your scan in the exam.", "te": "వేరే orders కూడా safe కావచ్చు, example గా P1, P3, P4, P2, P0. ప్రతి need fit అయ్యే ఏ order అయినా accept చేస్తారు, కాబట్టి exam లో మీ scan ను show చేయండి."}, "do": [{"action": "reset", "target": "log"}]}]}, {"id": "request", "steps": [{"say": {"en": "Now P1 asks for one more A and two more C: the request one zero two. Should the system grant it?", "te": "ఇప్పుడు P1, one more A, two more C అడుగుతుంది: request one zero two. System దాన్ని grant చేయాలా?"}, "do": [{"action": "replace", "target": "heading", "text": "Stage 4 of 4: a new request"}, {"action": "hide", "target": "log"}, {"action": "show", "target": "req", "delay": 0.2}, {"action": "set", "target": "mat[0][4]", "value": "F"}, {"action": "set", "target": "mat[1][4]", "value": "F"}, {"action": "set", "target": "mat[2][4]", "value": "F"}, {"action": "set", "target": "mat[3][4]", "value": "F"}, {"action": "set", "target": "mat[4][4]", "value": "F"}, {"action": "reset", "target": "mat"}, {"action": "replace", "target": "status", "text": "Available = (3, 3, 2)", "delay": 0.3}]}, {"say": {"en": "First check: a request may not exceed the process''s need. One zero two is within P1''s need, one two two.", "te": "First check: request, process need ను exceed చేయకూడదు. One zero two, P1 need అయిన one two two within లోనే ఉంది."}, "do": [{"action": "reveal", "target": "req[1]"}, {"action": "highlight", "target": "mat[1][3]"}]}, {"say": {"en": "Second check: it may not exceed what is available, three three two. It does not, so the resources exist.", "te": "Second check: అది available అయిన three three two ను exceed చేయకూడదు. చేయదు, కాబట్టి resources ఉన్నాయి."}, "do": [{"action": "reveal", "target": "req[2]"}, {"action": "reset", "target": "mat"}]}, {"say": {"en": "Now we pretend to grant it. Available drops to two three zero.", "te": "ఇప్పుడు grant చేసినట్టు pretend చేస్తాం. Available, two three zero కు drop అవుతుంది."}, "do": [{"action": "reveal", "target": "req[3]"}, {"action": "replace", "target": "status", "text": "Available = (2, 3, 0)    (pretend)", "delay": 0.5}]}, {"say": {"en": "P1''s allocation rises to three zero two, and its need falls to zero two zero.", "te": "P1 allocation three zero two కు rise అవుతుంది, దాని need zero two zero కు fall అవుతుంది."}, "do": [{"action": "reveal", "target": "req[4]"}, {"action": "highlight", "target": "mat[1]"}, {"action": "set", "target": "mat[1][1]", "value": "3 0 2", "delay": 0.4}, {"action": "set", "target": "mat[1][3]", "value": "0 2 0", "delay": 0.6}]}, {"say": {"en": "The request is granted only if this new state is still safe, so we run the safety check again.", "te": "ఈ new state ఇంకా safe అయితేనే request grant అవుతుంది, కాబట్టి safety check మళ్ళీ run చేస్తాం."}, "do": [{"action": "reset", "target": "mat"}, {"action": "hide", "target": "req"}, {"action": "show", "target": "log2", "delay": 0.3}]}, {"say": {"en": "With work two three zero, P0 does not fit, but P1 now needs only zero two zero, and fits. Work becomes five three two.", "te": "Work two three zero తో P0 fit కాదు, కానీ P1 కు ఇప్పుడు zero two zero మాత్రమే need, fit అవుతుంది. Work five three two అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[1]"}, {"action": "add_row", "target": "log2", "values": ["P1", "0 2 0 ≤ 2 3 0: yes", "5 3 2"]}, {"action": "set", "target": "mat[1][4]", "value": "T", "delay": 0.6}]}, {"say": {"en": "P2 still does not fit. P3 fits, making seven four three, and then P4 fits, making seven four five.", "te": "P2 ఇంకా fit కాదు. P3 fit అయి seven four three, తర్వాత P4 fit అయి seven four five అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[2..5]"}, {"action": "add_row", "target": "log2", "values": ["P2", "6 0 0 ≤ 5 3 2: no", ""]}, {"action": "add_row", "target": "log2", "values": ["P3", "0 1 1 ≤ 5 3 2: yes", "7 4 3"], "delay": 0.3}, {"action": "add_row", "target": "log2", "values": ["P4", "4 3 1 ≤ 7 4 3: yes", "7 4 5"], "delay": 0.6}, {"action": "set", "target": "mat[3][4]", "value": "T", "delay": 0.4}, {"action": "set", "target": "mat[4][4]", "value": "T", "delay": 0.7}]}, {"say": {"en": "On the second pass P0 fits, giving seven five five, and P2 fits, giving ten five seven.", "te": "Second pass లో P0 fit అయి seven five five, P2 fit అయి ten five seven వస్తుంది."}, "do": [{"action": "highlight", "target": "mat[0]"}, {"action": "add_row", "target": "log2", "values": ["P0", "7 4 3 ≤ 7 4 5: yes", "7 5 5"]}, {"action": "add_row", "target": "log2", "values": ["P2", "6 0 0 ≤ 7 5 5: yes", "10 5 7"], "delay": 0.5}, {"action": "set", "target": "mat[0][4]", "value": "T", "delay": 0.3}, {"action": "set", "target": "mat[2][4]", "value": "T", "delay": 0.7}]}, {"say": {"en": "Every process can still finish, so the new state is safe and the request is granted. The sequence is again P1, P3, P4, P0, P2.", "te": "ప్రతి process ఇంకా finish అవ్వగలదు, కాబట్టి new state safe, request grant అవుతుంది. Sequence మళ్ళీ P1, P3, P4, P0, P2."}, "do": [{"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Finish"}, {"action": "replace", "target": "status", "text": "Safe: request (1, 0, 2) granted to P1", "delay": 0.4}]}, {"say": {"en": "If some process could never fit, the request would be refused and P1 would wait, even though the resources are free.", "te": "ఏదైనా process ఎప్పటికీ fit కాకపోతే, request refuse అవుతుంది, resources free గా ఉన్నా P1 wait చేయాలి."}, "do": [{"action": "reset", "target": "log2"}]}]}, {"id": "recap", "steps": [{"say": {"en": "To recap the four stages. One: need is max minus allocation.", "te": "Four stages ను recap చేద్దాం. One: need అంటే max minus allocation."}, "do": [{"action": "replace", "target": "heading", "text": "Recap"}, {"action": "hide", "target": "mat"}, {"action": "hide", "target": "log2"}, {"action": "hide", "target": "status"}, {"action": "show", "target": "roadmap", "delay": 0.3}, {"action": "mark", "target": "roadmap[0]", "delay": 0.6}]}, {"say": {"en": "Two: available is the total minus everything allocated.", "te": "Two: available అంటే total minus allocate అయినవి అన్నీ."}, "do": [{"action": "mark", "target": "roadmap[1]"}]}, {"say": {"en": "Three: the safety check grows work one finished process at a time. The state is safe if every process can finish.", "te": "Three: safety check లో ఒక్కో process finish అయినప్పుడు work grow అవుతుంది. ప్రతి process finish అవ్వగలిగితే state safe."}, "do": [{"action": "mark", "target": "roadmap[2]"}]}, {"say": {"en": "Four: a request is granted only if it fits the need, fits what is available, and leaves the state safe.", "te": "Four: request need లో fit అయి, available లో fit అయి, state ను safe గా ఉంచితేనే grant అవుతుంది."}, "do": [{"action": "mark", "target": "roadmap[3]"}]}]}]}', '[{"scene": "overview", "steps": 4, "seconds": 29, "opens_with": "Banker''s algorithm అంటే, deadlock రాకుండా, ఒక process కు resources ఇవ్వడం safe అవునా కాదా అని operating system decide చే"}, {"scene": "problem", "steps": 5, "seconds": 43, "opens_with": "ఇది problem. ఇక్కడ P0 నుంచి P4 వరకు five processes, A, B, C అనే three resource types ఉన్నాయి."}, {"scene": "need", "steps": 6, "seconds": 48, "opens_with": "First question: ప్రతి process ఇంకా ఎంత more అడగగలదు? దాన్నే need అంటారు."}, {"scene": "available", "steps": 4, "seconds": 28, "opens_with": "Next, ఇప్పుడు ప్రతి resource ఎంత free గా ఉంది? దీన్నే available vector అంటారు."}, {"scene": "safety", "steps": 19, "seconds": 159, "opens_with": "ఇప్పుడు main question: ప్రతి process finish అయ్యే order ఏదైనా ఉందా? ఉంటే, ఆ state safe."}, {"scene": "request", "steps": 11, "seconds": 98, "opens_with": "ఇప్పుడు P1, one more A, two more C అడుగుతుంది: request one zero two. System దాన్ని grant చేయాలా?"}, {"scene": "recap", "steps": 4, "seconds": 28, "opens_with": "Four stages ను recap చేద్దాం. One: need అంటే max minus allocation."}]', 0, now(), now(), now(), 'os') on conflict (id) do nothing;
insert into videos (id, user_id, title, language, speaker, voiced, captions, status, progress, error, seconds, steps, characters, is_public, script, outline, views, created_at, finished_at, published_at, subject) values ('e410d29c3f80', '52061686-0664-40b2-8dd3-99457b33ce76', 'Banker''s algorithm, worked step by step', 'en', 'Vasudha', true, true, 'done', 'finished', NULL, 386.633, 53, 4619, true, '{"version": 1, "title": "OS: Banker''s algorithm, worked step by step", "objects": [{"id": "heading", "type": "text", "region": "title", "text": "Banker''s algorithm: avoiding deadlock"}, {"id": "roadmap", "type": "table", "region": "center", "columns": ["stage", "what we find", "why"], "rows": [[1, "Need matrix", "what each process may still ask for"], [2, "Available", "what is free right now"], [3, "Safety check", "an order in which every process can finish"], [4, "A new request", "grant it only if the state stays safe"]]}, {"id": "mat", "type": "table", "region": "left", "columns": ["process", "Allocation", "Max", "Need", "Finish"], "rows": [["P0", "0 1 0", "7 5 3", "", "F"], ["P1", "2 0 0", "3 2 2", "", "F"], ["P2", "3 0 2", "9 0 2", "", "F"], ["P3", "2 1 1", "2 2 2", "", "F"], ["P4", "0 0 2", "4 3 3", "", "F"]]}, {"id": "status", "type": "text", "region": "bottom", "text": "Total: A = 10, B = 5, C = 7"}, {"id": "needeq", "type": "math", "region": "right", "lines": ["\"Need\" = \"Max\" - \"Allocation\"", "P_0 : (7, 5, 3) - (0, 1, 0) = (7, 4, 3)", "P_1 : (3, 2, 2) - (2, 0, 0) = (1, 2, 2)", "P_2, P_3, P_4 : (6, 0, 0), (0, 1, 1), (4, 3, 1)"]}, {"id": "avail", "type": "math", "region": "right", "lines": ["\"Available\" = \"Total\" - sum \"Allocation\"", "sum \"Allocation\" = (7, 2, 5)", "(10, 5, 7) - (7, 2, 5) = (3, 3, 2)"]}, {"id": "rule", "type": "math", "region": "right", "lines": ["\"Work\" = \"Available\" = (3, 3, 2)", "\"if\" \"Need\"_i <= \"Work\" :", "\"Work\" = \"Work\" + \"Allocation\"_i , quad \"Finish\"_i = T"]}, {"id": "log", "type": "table", "region": "right", "columns": ["check", "Need ≤ Work?", "Work after"], "rows": [["P0", "7 4 3 ≤ 3 3 2: no", ""]]}, {"id": "req", "type": "math", "region": "right", "lines": ["\"Request\"_1 = (1, 0, 2)", "(1, 0, 2) <= \"Need\"_1 = (1, 2, 2) quad \"yes\"", "(1, 0, 2) <= \"Available\" = (3, 3, 2) quad \"yes\"", "\"Available\" = (3, 3, 2) - (1, 0, 2) = (2, 3, 0)", "\"Allocation\"_1 = (2, 0, 0) + (1, 0, 2) = (3, 0, 2)"]}, {"id": "log2", "type": "table", "region": "right", "columns": ["check", "Need ≤ Work?", "Work after"], "rows": [["P0", "7 4 3 ≤ 2 3 0: no", ""]]}], "scenes": [{"id": "overview", "steps": [{"say": {"en": "Banker''s algorithm decides whether the operating system can safely give resources to a process, without ever reaching deadlock.", "te": "Banker''s algorithm అంటే, deadlock రాకుండా, ఒక process కు resources ఇవ్వడం safe అవునా కాదా అని operating system decide చేసే method."}, "do": [{"action": "write", "target": "heading"}]}, {"say": {"en": "It is named after a bank, which lends money only if it can still pay every customer back in some order.", "te": "దీనికి bank పేరు ఎందుకంటే, ఒక bank తన customers అందరికీ ఏదో ఒక order లో pay చేయగలిగితేనే loan ఇస్తుంది."}, "do": []}, {"say": {"en": "We will work one exam problem through four stages.", "te": "మనం ఒక exam problem ను four stages లో solve చేస్తాం."}, "do": [{"action": "show", "target": "roadmap"}]}, {"say": {"en": "First the need matrix, then the available vector, then the safety check, and last a new request.", "te": "First need matrix, తర్వాత available vector, తర్వాత safety check, last గా ఒక new request."}, "do": [{"action": "highlight", "target": "roadmap[0]"}, {"action": "highlight", "target": "roadmap[1]", "delay": 0.25}, {"action": "highlight", "target": "roadmap[2]", "delay": 0.5}, {"action": "highlight", "target": "roadmap[3]", "delay": 0.75}]}]}, {"id": "problem", "steps": [{"say": {"en": "Here is the problem. There are five processes, P0 to P4, and three resource types, A, B and C.", "te": "ఇది problem. ఇక్కడ P0 నుంచి P4 వరకు five processes, A, B, C అనే three resource types ఉన్నాయి."}, "do": [{"action": "replace", "target": "heading", "text": "The problem"}, {"action": "hide", "target": "roadmap"}, {"action": "show", "target": "mat", "delay": 0.2}]}, {"say": {"en": "The system has 10 instances of A, 5 of B and 7 of C in total.", "te": "System లో total గా A వి 10, B వి 5, C వి 7 instances ఉన్నాయి."}, "do": [{"action": "write", "target": "status"}]}, {"say": {"en": "The allocation column is what each process holds right now. P0 holds zero A, one B and zero C.", "te": "Allocation column అంటే ప్రతి process ఇప్పుడు hold చేస్తున్న resources. P0 దగ్గర zero A, one B, zero C ఉన్నాయి."}, "do": [{"action": "highlight", "target": "mat.Allocation"}, {"action": "highlight", "target": "mat[0][1]", "delay": 0.55}]}, {"say": {"en": "The max column is the most each process may ever ask for. P0 may need up to seven A, five B and three C.", "te": "Max column అంటే ప్రతి process ever అడగగలిగే maximum. P0 కు up to seven A, five B, three C అవసరం కావచ్చు."}, "do": [{"action": "highlight", "target": "mat.Max"}, {"action": "highlight", "target": "mat[0][2]", "delay": 0.55}]}, {"say": {"en": "Every process declares its max in advance. That is what lets the system plan ahead.", "te": "ప్రతి process తన max ను advance గా declare చేస్తుంది. అందుకే system advance గా plan చేయగలదు."}, "do": [{"action": "reset", "target": "mat"}]}]}, {"id": "need", "steps": [{"say": {"en": "The first question is how much more each process can still ask for. That is called its need.", "te": "First question: ప్రతి process ఇంకా ఎంత more అడగగలదు? దాన్నే need అంటారు."}, "do": [{"action": "replace", "target": "heading", "text": "Stage 1 of 4: the need matrix"}, {"action": "show", "target": "needeq"}]}, {"say": {"en": "Need is max minus allocation: the most it may want, minus what it already holds.", "te": "Need అంటే max minus allocation: అది want చేసే maximum లో నుంచి already hold చేస్తున్నది minus చేస్తాం."}, "do": [{"action": "highlight", "target": "needeq[0]"}]}, {"say": {"en": "For P0, seven five three minus zero one zero gives seven four three.", "te": "P0 కు, seven five three minus zero one zero చేస్తే seven four three వస్తుంది."}, "do": [{"action": "reveal", "target": "needeq[1]"}, {"action": "highlight", "target": "mat[0]"}, {"action": "set", "target": "mat[0][3]", "value": "7 4 3", "delay": 0.5}]}, {"say": {"en": "For P1, three two two minus two zero zero gives one two two.", "te": "P1 కు, three two two minus two zero zero చేస్తే one two two వస్తుంది."}, "do": [{"action": "reveal", "target": "needeq[2]"}, {"action": "highlight", "target": "mat[1]"}, {"action": "set", "target": "mat[1][3]", "value": "1 2 2", "delay": 0.5}]}, {"say": {"en": "The same subtraction for P2, P3 and P4 gives six zero zero, zero one one, and four three one.", "te": "అదే subtraction P2, P3, P4 కు చేస్తే six zero zero, zero one one, four three one వస్తాయి."}, "do": [{"action": "reveal", "target": "needeq[3]"}, {"action": "highlight", "target": "mat[2..5]"}, {"action": "set", "target": "mat[2][3]", "value": "6 0 0", "delay": 0.3}, {"action": "set", "target": "mat[3][3]", "value": "0 1 1", "delay": 0.5}, {"action": "set", "target": "mat[4][3]", "value": "4 3 1", "delay": 0.7}]}, {"say": {"en": "A quick check: no need can be negative, because no process holds more than its max.", "te": "ఒక quick check: ఏ need కూడా negative కాకూడదు, ఎందుకంటే ఏ process కూడా తన max కంటే more hold చేయదు."}, "do": [{"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Need"}]}]}, {"id": "available", "steps": [{"say": {"en": "Next, how much of each resource is free right now. This is the available vector.", "te": "Next, ఇప్పుడు ప్రతి resource ఎంత free గా ఉంది? దీన్నే available vector అంటారు."}, "do": [{"action": "replace", "target": "heading", "text": "Stage 2 of 4: what is available"}, {"action": "hide", "target": "needeq"}, {"action": "show", "target": "avail", "delay": 0.2}]}, {"say": {"en": "Available is the total minus everything that is already allocated.", "te": "Available అంటే total minus already allocate అయినవి అన్నీ."}, "do": [{"action": "highlight", "target": "avail[0]"}]}, {"say": {"en": "Add down the allocation column. For A, zero plus two plus three plus two plus zero is seven. B adds to two, and C to five.", "te": "Allocation column ను add చేద్దాం. A కు zero plus two plus three plus two plus zero, seven. B add చేస్తే two, C add చేస్తే five."}, "do": [{"action": "reveal", "target": "avail[1]"}, {"action": "highlight", "target": "mat.Allocation"}]}, {"say": {"en": "Ten five seven minus seven two five leaves three three two free.", "te": "Ten five seven minus seven two five చేస్తే three three two free గా ఉంటాయి."}, "do": [{"action": "reveal", "target": "avail[2]"}, {"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Need"}, {"action": "replace", "target": "status", "text": "Total (10, 5, 7)    Available (3, 3, 2)", "delay": 0.5}]}]}, {"id": "safety", "steps": [{"say": {"en": "Now the main question: is there an order in which every process can finish? If there is, the state is safe.", "te": "ఇప్పుడు main question: ప్రతి process finish అయ్యే order ఏదైనా ఉందా? ఉంటే, ఆ state safe."}, "do": [{"action": "replace", "target": "heading", "text": "Stage 3 of 4: the safety check"}, {"action": "hide", "target": "avail"}, {"action": "show", "target": "rule", "delay": 0.2}]}, {"say": {"en": "We start with work equal to available, three three two, and every process marked not finished.", "te": "Work = available, అంటే three three two తో start చేస్తాం, ప్రతి process not finished గా ఉంటుంది."}, "do": [{"action": "highlight", "target": "rule[0]"}, {"action": "highlight", "target": "mat.Finish"}, {"action": "replace", "target": "status", "text": "Work = (3, 3, 2)", "delay": 0.5}]}, {"say": {"en": "The rule: if a process''s need fits in work, it can run to the end and then give back everything it holds.", "te": "Rule: ఒక process need, work లో fit అయితే, అది end వరకు run అయి, తను hold చేసినవన్నీ return చేస్తుంది."}, "do": [{"action": "reveal", "target": "rule[1]"}, {"action": "highlight", "target": "rule[1]"}]}, {"say": {"en": "So work grows by that process''s allocation, and we mark it finished.", "te": "కాబట్టి work కు ఆ process allocation add అవుతుంది, దాన్ని finished గా mark చేస్తాం."}, "do": [{"action": "reveal", "target": "rule[2]"}, {"action": "highlight", "target": "rule[2]"}]}, {"say": {"en": "We scan from P0 to P4, and go back to the top until no process can move.", "te": "P0 నుంచి P4 వరకు scan చేస్తాం, ఏ process కూడా move చేయలేనంత వరకు మళ్ళీ top నుంచి start చేస్తాం."}, "do": [{"action": "reset", "target": "rule"}, {"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Need"}]}, {"say": {"en": "P0 needs seven four three, but work has only three A. Seven does not fit in three, so P0 waits.", "te": "P0 కు seven four three need, కానీ work లో three A మాత్రమే. Seven, three లో fit కాదు, కాబట్టి P0 wait చేస్తుంది."}, "do": [{"action": "hide", "target": "rule"}, {"action": "show", "target": "log"}, {"action": "highlight", "target": "mat[0]"}]}, {"say": {"en": "P1 needs one two two. One is at most three, two is at most three, and two is at most two, so it fits.", "te": "P1 కు one two two need. One, three కంటే less, two, three కంటే less, two, two కి equal, కాబట్టి fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[1]"}, {"action": "add_row", "target": "log", "values": ["P1", "1 2 2 ≤ 3 3 2: yes", ""]}]}, {"say": {"en": "P1 finishes and returns two zero zero. Work becomes three three two plus two zero zero, which is five three two.", "te": "P1 finish అయి two zero zero return చేస్తుంది. Work, three three two plus two zero zero, అంటే five three two."}, "do": [{"action": "set", "target": "mat[1][4]", "value": "T"}, {"action": "set", "target": "log[1][2]", "value": "5 3 2", "delay": 0.4}, {"action": "replace", "target": "status", "text": "Work = (5, 3, 2)    order: P1", "delay": 0.6}]}, {"say": {"en": "P2 needs six A, but work has five. It waits.", "te": "P2 కు six A need, కానీ work లో five మాత్రమే. అది wait చేస్తుంది."}, "do": [{"action": "highlight", "target": "mat[2]"}, {"action": "add_row", "target": "log", "values": ["P2", "6 0 0 ≤ 5 3 2: no", ""]}]}, {"say": {"en": "P3 needs zero one one, which fits in five three two.", "te": "P3 కు zero one one need, అది five three two లో fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[3]"}, {"action": "add_row", "target": "log", "values": ["P3", "0 1 1 ≤ 5 3 2: yes", ""]}]}, {"say": {"en": "P3 returns two one one, so work becomes seven four three.", "te": "P3 two one one return చేస్తుంది, కాబట్టి work seven four three అవుతుంది."}, "do": [{"action": "set", "target": "mat[3][4]", "value": "T"}, {"action": "set", "target": "log[3][2]", "value": "7 4 3", "delay": 0.3}, {"action": "replace", "target": "status", "text": "Work = (7, 4, 3)    order: P1, P3", "delay": 0.5}]}, {"say": {"en": "P4 needs four three one, which fits in seven four three.", "te": "P4 కు four three one need, అది seven four three లో fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[4]"}, {"action": "add_row", "target": "log", "values": ["P4", "4 3 1 ≤ 7 4 3: yes", ""]}]}, {"say": {"en": "P4 returns zero zero two, so work becomes seven four five.", "te": "P4 zero zero two return చేస్తుంది, కాబట్టి work seven four five అవుతుంది."}, "do": [{"action": "set", "target": "mat[4][4]", "value": "T"}, {"action": "set", "target": "log[4][2]", "value": "7 4 5", "delay": 0.3}, {"action": "replace", "target": "status", "text": "Work = (7, 4, 5)    order: P1, P3, P4", "delay": 0.5}]}, {"say": {"en": "Back to the top. P0 needs seven four three, and now that fits in seven four five.", "te": "మళ్ళీ top కు. P0 కు seven four three need, ఇప్పుడు అది seven four five లో fit అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[0]"}, {"action": "add_row", "target": "log", "values": ["P0", "7 4 3 ≤ 7 4 5: yes", ""]}]}, {"say": {"en": "P0 returns zero one zero, so work becomes seven five five.", "te": "P0 zero one zero return చేస్తుంది, కాబట్టి work seven five five అవుతుంది."}, "do": [{"action": "set", "target": "mat[0][4]", "value": "T"}, {"action": "set", "target": "log[5][2]", "value": "7 5 5", "delay": 0.3}, {"action": "replace", "target": "status", "text": "Work = (7, 5, 5)    order: P1, P3, P4, P0", "delay": 0.5}]}, {"say": {"en": "P2 needs six zero zero, which fits in seven five five. It returns three zero two, and work becomes ten five seven.", "te": "P2 కు six zero zero need, అది seven five five లో fit అవుతుంది. అది three zero two return చేస్తుంది, work ten five seven అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[2]"}, {"action": "add_row", "target": "log", "values": ["P2", "6 0 0 ≤ 7 5 5: yes", ""]}, {"action": "set", "target": "mat[2][4]", "value": "T", "delay": 0.5}, {"action": "set", "target": "log[6][2]", "value": "10 5 7", "delay": 0.6}]}, {"say": {"en": "Every process finished, so the state is safe. The safe sequence is P1, P3, P4, P0, P2.", "te": "ప్రతి process finish అయ్యింది, కాబట్టి ఈ state safe. Safe sequence: P1, P3, P4, P0, P2."}, "do": [{"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Finish"}, {"action": "replace", "target": "status", "text": "Safe sequence: P1 → P3 → P4 → P0 → P2", "delay": 0.3}]}, {"say": {"en": "Check: the final work, ten five seven, equals the total. Every resource came back, as it must.", "te": "Check: final work ten five seven, total కి equal. ప్రతి resource back వచ్చింది, అలాగే రావాలి."}, "do": [{"action": "highlight", "target": "log[6][2]"}]}, {"say": {"en": "Other orders can be safe too, such as P1, P3, P4, P2, P0. Any order where each need fits is accepted, so show your scan in the exam.", "te": "వేరే orders కూడా safe కావచ్చు, example గా P1, P3, P4, P2, P0. ప్రతి need fit అయ్యే ఏ order అయినా accept చేస్తారు, కాబట్టి exam లో మీ scan ను show చేయండి."}, "do": [{"action": "reset", "target": "log"}]}]}, {"id": "request", "steps": [{"say": {"en": "Now P1 asks for one more A and two more C: the request one zero two. Should the system grant it?", "te": "ఇప్పుడు P1, one more A, two more C అడుగుతుంది: request one zero two. System దాన్ని grant చేయాలా?"}, "do": [{"action": "replace", "target": "heading", "text": "Stage 4 of 4: a new request"}, {"action": "hide", "target": "log"}, {"action": "show", "target": "req", "delay": 0.2}, {"action": "set", "target": "mat[0][4]", "value": "F"}, {"action": "set", "target": "mat[1][4]", "value": "F"}, {"action": "set", "target": "mat[2][4]", "value": "F"}, {"action": "set", "target": "mat[3][4]", "value": "F"}, {"action": "set", "target": "mat[4][4]", "value": "F"}, {"action": "reset", "target": "mat"}, {"action": "replace", "target": "status", "text": "Available = (3, 3, 2)", "delay": 0.3}]}, {"say": {"en": "First check: a request may not exceed the process''s need. One zero two is within P1''s need, one two two.", "te": "First check: request, process need ను exceed చేయకూడదు. One zero two, P1 need అయిన one two two within లోనే ఉంది."}, "do": [{"action": "reveal", "target": "req[1]"}, {"action": "highlight", "target": "mat[1][3]"}]}, {"say": {"en": "Second check: it may not exceed what is available, three three two. It does not, so the resources exist.", "te": "Second check: అది available అయిన three three two ను exceed చేయకూడదు. చేయదు, కాబట్టి resources ఉన్నాయి."}, "do": [{"action": "reveal", "target": "req[2]"}, {"action": "reset", "target": "mat"}]}, {"say": {"en": "Now we pretend to grant it. Available drops to two three zero.", "te": "ఇప్పుడు grant చేసినట్టు pretend చేస్తాం. Available, two three zero కు drop అవుతుంది."}, "do": [{"action": "reveal", "target": "req[3]"}, {"action": "replace", "target": "status", "text": "Available = (2, 3, 0)    (pretend)", "delay": 0.5}]}, {"say": {"en": "P1''s allocation rises to three zero two, and its need falls to zero two zero.", "te": "P1 allocation three zero two కు rise అవుతుంది, దాని need zero two zero కు fall అవుతుంది."}, "do": [{"action": "reveal", "target": "req[4]"}, {"action": "highlight", "target": "mat[1]"}, {"action": "set", "target": "mat[1][1]", "value": "3 0 2", "delay": 0.4}, {"action": "set", "target": "mat[1][3]", "value": "0 2 0", "delay": 0.6}]}, {"say": {"en": "The request is granted only if this new state is still safe, so we run the safety check again.", "te": "ఈ new state ఇంకా safe అయితేనే request grant అవుతుంది, కాబట్టి safety check మళ్ళీ run చేస్తాం."}, "do": [{"action": "reset", "target": "mat"}, {"action": "hide", "target": "req"}, {"action": "show", "target": "log2", "delay": 0.3}]}, {"say": {"en": "With work two three zero, P0 does not fit, but P1 now needs only zero two zero, and fits. Work becomes five three two.", "te": "Work two three zero తో P0 fit కాదు, కానీ P1 కు ఇప్పుడు zero two zero మాత్రమే need, fit అవుతుంది. Work five three two అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[1]"}, {"action": "add_row", "target": "log2", "values": ["P1", "0 2 0 ≤ 2 3 0: yes", "5 3 2"]}, {"action": "set", "target": "mat[1][4]", "value": "T", "delay": 0.6}]}, {"say": {"en": "P2 still does not fit. P3 fits, making seven four three, and then P4 fits, making seven four five.", "te": "P2 ఇంకా fit కాదు. P3 fit అయి seven four three, తర్వాత P4 fit అయి seven four five అవుతుంది."}, "do": [{"action": "highlight", "target": "mat[2..5]"}, {"action": "add_row", "target": "log2", "values": ["P2", "6 0 0 ≤ 5 3 2: no", ""]}, {"action": "add_row", "target": "log2", "values": ["P3", "0 1 1 ≤ 5 3 2: yes", "7 4 3"], "delay": 0.3}, {"action": "add_row", "target": "log2", "values": ["P4", "4 3 1 ≤ 7 4 3: yes", "7 4 5"], "delay": 0.6}, {"action": "set", "target": "mat[3][4]", "value": "T", "delay": 0.4}, {"action": "set", "target": "mat[4][4]", "value": "T", "delay": 0.7}]}, {"say": {"en": "On the second pass P0 fits, giving seven five five, and P2 fits, giving ten five seven.", "te": "Second pass లో P0 fit అయి seven five five, P2 fit అయి ten five seven వస్తుంది."}, "do": [{"action": "highlight", "target": "mat[0]"}, {"action": "add_row", "target": "log2", "values": ["P0", "7 4 3 ≤ 7 4 5: yes", "7 5 5"]}, {"action": "add_row", "target": "log2", "values": ["P2", "6 0 0 ≤ 7 5 5: yes", "10 5 7"], "delay": 0.5}, {"action": "set", "target": "mat[0][4]", "value": "T", "delay": 0.3}, {"action": "set", "target": "mat[2][4]", "value": "T", "delay": 0.7}]}, {"say": {"en": "Every process can still finish, so the new state is safe and the request is granted. The sequence is again P1, P3, P4, P0, P2.", "te": "ప్రతి process ఇంకా finish అవ్వగలదు, కాబట్టి new state safe, request grant అవుతుంది. Sequence మళ్ళీ P1, P3, P4, P0, P2."}, "do": [{"action": "reset", "target": "mat"}, {"action": "mark", "target": "mat.Finish"}, {"action": "replace", "target": "status", "text": "Safe: request (1, 0, 2) granted to P1", "delay": 0.4}]}, {"say": {"en": "If some process could never fit, the request would be refused and P1 would wait, even though the resources are free.", "te": "ఏదైనా process ఎప్పటికీ fit కాకపోతే, request refuse అవుతుంది, resources free గా ఉన్నా P1 wait చేయాలి."}, "do": [{"action": "reset", "target": "log2"}]}]}, {"id": "recap", "steps": [{"say": {"en": "To recap the four stages. One: need is max minus allocation.", "te": "Four stages ను recap చేద్దాం. One: need అంటే max minus allocation."}, "do": [{"action": "replace", "target": "heading", "text": "Recap"}, {"action": "hide", "target": "mat"}, {"action": "hide", "target": "log2"}, {"action": "hide", "target": "status"}, {"action": "show", "target": "roadmap", "delay": 0.3}, {"action": "mark", "target": "roadmap[0]", "delay": 0.6}]}, {"say": {"en": "Two: available is the total minus everything allocated.", "te": "Two: available అంటే total minus allocate అయినవి అన్నీ."}, "do": [{"action": "mark", "target": "roadmap[1]"}]}, {"say": {"en": "Three: the safety check grows work one finished process at a time. The state is safe if every process can finish.", "te": "Three: safety check లో ఒక్కో process finish అయినప్పుడు work grow అవుతుంది. ప్రతి process finish అవ్వగలిగితే state safe."}, "do": [{"action": "mark", "target": "roadmap[2]"}]}, {"say": {"en": "Four: a request is granted only if it fits the need, fits what is available, and leaves the state safe.", "te": "Four: request need లో fit అయి, available లో fit అయి, state ను safe గా ఉంచితేనే grant అవుతుంది."}, "do": [{"action": "mark", "target": "roadmap[3]"}]}]}]}', '[{"scene": "overview", "steps": 4, "seconds": 27, "opens_with": "Banker''s algorithm decides whether the operating system can safely give resources to a process, without ever reaching de"}, {"scene": "problem", "steps": 5, "seconds": 38, "opens_with": "Here is the problem. There are five processes, P0 to P4, and three resource types, A, B and C."}, {"scene": "need", "steps": 6, "seconds": 40, "opens_with": "The first question is how much more each process can still ask for. That is called its need."}, {"scene": "available", "steps": 4, "seconds": 29, "opens_with": "Next, how much of each resource is free right now. This is the available vector."}, {"scene": "safety", "steps": 19, "seconds": 137, "opens_with": "Now the main question: is there an order in which every process can finish? If there is, the state is safe."}, {"scene": "request", "steps": 11, "seconds": 90, "opens_with": "Now P1 asks for one more A and two more C: the request one zero two. Should the system grant it?"}, {"scene": "recap", "steps": 4, "seconds": 26, "opens_with": "To recap the four stages. One: need is max minus allocation."}]', 0, now(), now(), now(), 'os') on conflict (id) do nothing;
